<?php
require __DIR__.'/bootstrap.php';$u=require_user();$uid=(int)$u['id'];
if(method()==='GET'&&($_GET['action']??'')==='conversations'){$stmt=$db->prepare("SELECT other.id user_id,CONCAT(other.first_name,' ',other.last_name) name,MAX(m.created_at) last_message_at,SUBSTRING_INDEX(GROUP_CONCAT(m.body ORDER BY m.created_at DESC SEPARATOR '\n'),'\n',1) last_message,SUM(m.receiver_id=? AND m.read_at IS NULL) unread_count FROM messages m JOIN users other ON other.id=IF(m.sender_id=?,m.receiver_id,m.sender_id) WHERE m.sender_id=? OR m.receiver_id=? GROUP BY other.id,other.first_name,other.last_name ORDER BY last_message_at DESC");$stmt->bind_param('iiii',$uid,$uid,$uid,$uid);ok(db_all($stmt));}
if(method()==='GET'){$other=int_value($_GET['user_id']??null,'user');$product=isset($_GET['product_id'])?int_value($_GET['product_id'],'product'):0;$sql="SELECT m.*,CONCAT(s.first_name,' ',s.last_name) sender_name FROM messages m JOIN users s ON s.id=m.sender_id WHERE ((m.sender_id=? AND m.receiver_id=?) OR (m.sender_id=? AND m.receiver_id=?))";if($product)$sql.=' AND m.product_id=?';$sql.=' ORDER BY m.created_at';$stmt=$db->prepare($sql);if($product)$stmt->bind_param('iiiii',$uid,$other,$other,$uid,$product);else$stmt->bind_param('iiii',$uid,$other,$other,$uid);$rows=db_all($stmt);$stmt=$db->prepare('UPDATE messages SET read_at=NOW() WHERE receiver_id=? AND sender_id=? AND read_at IS NULL');$stmt->bind_param('ii',$uid,$other);$stmt->execute();ok($rows);}
if(method()==='POST'){$in=input();$to=int_value($in['receiver_id']??null,'recipient');$product=isset($in['product_id'])?(int)$in['product_id']:null;$body=text_value($in,'body',2000);if($to===$uid)fail('Cannot message yourself.',422);$stmt=$db->prepare("SELECT CONCAT(first_name,' ',last_name) name FROM users WHERE id=? AND status='active'");$stmt->bind_param('i',$to);if(!db_one($stmt))fail('Recipient is unavailable.',404);$stmt=$db->prepare('INSERT INTO messages(sender_id,receiver_id,product_id,body) VALUES(?,?,?,?)');$stmt->bind_param('iiis',$uid,$to,$product,$body);$stmt->execute();$messageId=$stmt->insert_id;$sender=$u['name']??trim($u['first_name'].' '.$u['last_name']);notify_user($db,$to,'new_message','New message from '.$sender,mb_substr($body,0,180),['message_id'=>$messageId,'sender_id'=>$uid,'product_id'=>$product]);ok(['id'=>$messageId,'created_at'=>date('Y-m-d H:i:s')],'Message sent.',201);}fail('Method not allowed.',405);
